 'pulsar.nativeSave.appended':'{count} माप {name} में जोड़े गए; पूरी फ़ाइल फिर से डाउनलोड की गई।',
 'pulsar.results.persistence':'दर्ज किए गए माप इस ब्राउज़र टैब में रखे जाते हैं; पेज रीफ़्रेश या बंद करने पर वे हट जाते हैं। टूलबार में “जाँच सहेजें” उन्हें मौजूदा डेटा के साथ रखता है, और “जाँच पुनर्स्थापित करें” उन्हें वापस लाता है। उसका डाउनलोड इस बात की पुष्टि नहीं है कि फ़ाइल लिखी गई।',
 'pulsar.restored.note':'जाँच फ़ाइल से पुनर्स्थापित किया गया। पुनर्स्थापित रिसीवर रिकॉर्डिंग को .PLR फ़ाइल में लिखी हुई चिह्नित नहीं किया जाता।',
 'pulsar.results.count':'दर्ज किए गए माप: {count}',
 'pulsar.export.open':'दर्ज किए गए माप निर्यात करें (.csv)…',
 'pulsar.export.note':'“निर्यात” दर्ज किए गए माप को एक नई फ़ाइल में लिखता है, जिसका हेडर आप खुद लिखते हैं। यह मूल “सहेजें” नहीं है। इसके लिए कम से कम एक दर्ज किया गया माप चाहिए, और यह तब रुका रहता है जब कोई दूसरा डायलॉग खुला हो, कोई फ़ाइल पढ़ी जा रही हो, कोई रिसीवर रिकॉर्डिंग डेटा रखे हो या नया डेटा प्रतीक्षा में हो।',
 'pulsar.export.unavailable':'निर्यात अभी उपलब्ध नहीं है: इसके लिए एक दर्ज किया गया माप चाहिए, और कोई दूसरा डायलॉग, फ़ाइल पढ़ना, रिसीवर रिकॉर्डिंग या प्रतीक्षा में डेटा नहीं होना चाहिए।',
 'pulsar.export.heading':'दर्ज किए गए माप निर्यात करें',
 'pulsar.export.scope':'{count} दर्ज किए गए माप सूची के क्रम में निर्यात होते हैं, उन्हीं मानों के साथ जो “देखें” दिखाता है। जो रीडिंग दर्ज नहीं हुई हैं और “देखें” के जो बदलाव पुष्ट नहीं हुए, वे शामिल नहीं हैं। ये इस वेब विंडो में लिए गए माप हैं, जिनमें मॉडल से बनी रिसीवर रिकॉर्डिंग के माप भी शामिल हैं; फ़ाइल उन्हें मूल CLEA प्रेक्षण नहीं बनाती।',
 'pulsar.export.consequence':'यह मूल “सहेजें” नहीं है, जो कंप्यूटर की तिथि और समय तथा संग्रहीत नाम लिखता है। यहाँ हर हेडर पाठ ठीक वैसा ही लिखा जाता है जैसा आप लिखते हैं; इस कंप्यूटर, उसकी घड़ी या लॉगिन से कुछ नहीं लिया जाता। सूची “सहेजी नहीं गई” चिह्नित रहती है, और फ़ाइल सचमुच सहेजी जाती है या नहीं, यह आपका ब्राउज़र तय करता है।',
 'pulsar.export.format':'केवल छापने योग्य ASCII, बिना दोहरे उद्धरण चिह्नों के। कुछ भी काटा या बदला नहीं जाता: जो पाठ नहीं समाता, वह अस्वीकार हो जाता है। पंक्तियाँ CR LF पर समाप्त होती हैं।',
